// WinBox M2 message encoding/parsing + wire chunk framing.
//
// Byte-for-byte port of the `M2` and `M2Parser` classes from the MIT Python
// reference (tools/winbox/winbox_terminal_client.py). Every encoder is
// compared against golden hex vectors generated by the Python implementation.
//
// TLV layout: [key_low][key_high][namespace][type][value...]
// Namespaces: 0xFF = system, 0xFE = session, 0x00 = user (key_id, high byte 0).

function toBytes (value) {
  if (Buffer.isBuffer(value)) return value
  if (value instanceof Uint8Array) return Buffer.from(value)
  if (typeof value === 'string') return Buffer.from(value, 'utf8')
  if (Array.isArray(value)) return Buffer.from(value)
  throw new TypeError('byte buffer expected')
}

const M2_MAGIC = Buffer.from('M2', 'ascii')
export const CHUNK_MAX = 0xff

function keyHeader (keyTuple) {
  const tuple = Array.isArray(keyTuple) ? keyTuple : keyTuple.key
  if (!Array.isArray(tuple) || tuple.length !== 3) {
    throw new TypeError('key tuple [key_low, key_high, namespace] expected')
  }
  return Buffer.from([tuple[0] & 0xff, tuple[1] & 0xff, tuple[2] & 0xff])
}

function userKeyHeader (keyId) {
  return Buffer.from([keyId & 0xff, (keyId >> 8) & 0xff, 0x00])
}

function u32le (value) {
  const buf = Buffer.alloc(4)
  buf.writeUInt32LE(value >>> 0)
  return buf
}

function u16le (value) {
  const buf = Buffer.alloc(2)
  buf.writeUInt16LE(value)
  return buf
}

export class M2 {
  // System keys (namespace 0xFF)
  static SYS_TO = Object.freeze([0x01, 0x00, 0xff])
  static SYS_FROM = Object.freeze([0x02, 0x00, 0xff])
  static SYS_REQUEST = Object.freeze([0x05, 0x00, 0xff])
  static SYS_REQID = Object.freeze([0x06, 0x00, 0xff])
  static SYS_CMD = Object.freeze([0x07, 0x00, 0xff])
  // Session keys (namespace 0xFE)
  static SESSION_ID = Object.freeze([0x01, 0x00, 0xfe])
  static FE000C = Object.freeze([0x0c, 0x00, 0xfe])

  static encodeBool (keyTuple, value) {
    return Buffer.concat([keyHeader(keyTuple), Buffer.from([value ? 0x01 : 0x00])])
  }

  static encodeU8 (keyTuple, value) {
    return Buffer.concat([keyHeader(keyTuple), Buffer.from([0x09, value & 0xff])])
  }

  static encodeU8User (keyId, value) {
    return Buffer.concat([userKeyHeader(keyId), Buffer.from([0x09, value & 0xff])])
  }

  static encodeU32 (keyTuple, value) {
    return Buffer.concat([keyHeader(keyTuple), Buffer.from([0x08]), u32le(value)])
  }

  static encodeU32User (keyId, value) {
    return Buffer.concat([userKeyHeader(keyId), Buffer.from([0x08]), u32le(value)])
  }

  static encodeU32Array (keyTuple, values) {
    const parts = [keyHeader(keyTuple), Buffer.from([0x88]), u16le(values.length)]
    for (const value of values) parts.push(u32le(value))
    return Buffer.concat(parts)
  }

  static encodeStringUser (keyId, value) {
    const data = Buffer.from(String(value), 'utf8')
    if (data.length > 255) {
      return Buffer.concat([userKeyHeader(keyId), Buffer.from([0x20]), u16le(data.length), data])
    }
    return Buffer.concat([userKeyHeader(keyId), Buffer.from([0x21, data.length]), data])
  }

  static encodeRawUser (keyId, data) {
    const bytes = toBytes(data)
    if (bytes.length > 255) {
      return Buffer.concat([userKeyHeader(keyId), Buffer.from([0x30]), u16le(bytes.length), bytes])
    }
    return Buffer.concat([userKeyHeader(keyId), Buffer.from([0x31, bytes.length]), bytes])
  }

  static encodeEmbeddedMsgUser (keyId, innerMsgBody) {
    const inner = Buffer.concat([M2_MAGIC, toBytes(innerMsgBody)])
    if (inner.length > 255) {
      return Buffer.concat([userKeyHeader(keyId), Buffer.from([0x28]), u16le(inner.length), inner])
    }
    return Buffer.concat([userKeyHeader(keyId), Buffer.from([0x29, inner.length]), inner])
  }

  static _wrap (bodyParts) {
    return Buffer.concat([M2_MAGIC, ...bodyParts])
  }

  static buildInitialRequest (sourceId) {
    return M2._wrap([
      M2.encodeU32Array(M2.SYS_TO, [13, 4]),
      M2.encodeU32Array(M2.SYS_FROM, [0, sourceId]),
      M2.encodeBool(M2.SYS_REQUEST, true),
      M2.encodeU8(M2.SYS_REQID, 0),
      M2.encodeU8(M2.SYS_CMD, 7),
    ])
  }

  static buildEmptyLogin (sourceId, reqId, password, cols = 80, rows = 24) {
    const inner = M2.encodeU8User(1, 0)
    return M2._wrap([
      M2.encodeU32Array(M2.SYS_TO, [76]),
      M2.encodeU32Array(M2.SYS_FROM, [0, sourceId]),
      M2.encodeBool(M2.SYS_REQUEST, true),
      M2.encodeU32User(5, cols),
      M2.encodeU32User(6, rows),
      M2.encodeU8User(8, 0),
      M2.encodeU8(M2.SYS_REQID, reqId),
      M2.encodeU32(M2.SYS_CMD, 0x0a0065),
      M2.encodeEmbeddedMsgUser(11, inner),
      M2.encodeStringUser(7, 'vt102'),
      M2.encodeStringUser(1, password),
    ])
  }

  static buildEmptyData (sourceId, sessionId, counter, data = null) {
    const parts = [
      M2.encodeU32Array(M2.SYS_TO, [76]),
      M2.encodeU32Array(M2.SYS_FROM, [0, sourceId]),
      M2.encodeU32User(3, counter),
      M2.encodeU8(M2.SESSION_ID, sessionId),
      M2.encodeU32(M2.SYS_CMD, 0x0a0067),
    ]
    if (data !== null && data !== undefined) parts.push(M2.encodeRawUser(2, data))
    return M2._wrap(parts)
  }
}

// ---------------------------------------------------------------------------
// Parsing
// ---------------------------------------------------------------------------

function fieldOf (parsed, fullKey) {
  if (parsed instanceof Map) return parsed.get(fullKey)
  if (parsed && typeof parsed === 'object') return parsed[fullKey] ?? parsed[String(fullKey)]
  return undefined
}

function u16leAt (data, offset) {
  return data[offset] | (data[offset + 1] << 8)
}

function u32leAt (data, offset) {
  return (data[offset] |
    (data[offset + 1] << 8) |
    (data[offset + 2] << 16) |
    (data[offset + 3] << 24)) >>> 0
}

export class M2Parser {
  /**
   * Parse an M2 message into a Map<fullKey, {type, value}>.
   * Type markers mirror the Python tuples: bool/u8/u32/u64/u32_array/string/
   * raw/msg/str_array/msg_array. raw and msg values are Buffers; array values
   * for str_array/msg_array are null (their content is only skipped).
   */
  static parse (data) {
    const message = toBytes(data)
    const result = new Map()
    if (message.length < 2 || message[0] !== 0x4d || message[1] !== 0x32) return result

    let pos = 2
    while (pos < message.length) {
      if (pos + 4 > message.length) break

      const keyLow = message[pos]
      const keyHigh = message[pos + 1]
      const namespace = message[pos + 2]
      const typeByte = message[pos + 3]
      pos += 4

      const fullKey = (namespace << 16) | (keyHigh << 8) | keyLow
      const record = (type, value) => {
        result.set(fullKey, { fullKey, type, value })
      }

      if (typeByte === 0x00) {
        record('bool', false)
      } else if (typeByte === 0x01) {
        record('bool', true)
      } else if (typeByte === 0x09) {
        if (pos < message.length) {
          record('u8', message[pos])
          pos += 1
        }
      } else if (typeByte === 0x08) {
        if (pos + 4 <= message.length) {
          record('u32', u32leAt(message, pos))
          pos += 4
        }
      } else if (typeByte === 0x10) {
        if (pos + 8 <= message.length) {
          const big = message.readBigUInt64LE(pos)
          // The Python reference returns an arbitrary precision int; JSON
          // fixtures already round-trip through a double, so Number is what
          // comparing against those fixtures expects. u64 is not used by any
          // getter in this client.
          record('u64', Number(big))
          pos += 8
        }
      } else if (typeByte === 0x88) {
        if (pos + 2 <= message.length) {
          const count = u16leAt(message, pos)
          pos += 2
          const values = []
          for (let i = 0; i < count; i += 1) {
            if (pos + 4 <= message.length) {
              values.push(u32leAt(message, pos))
              pos += 4
            }
          }
          record('u32_array', values)
        }
      } else if (typeByte === 0x20) {
        if (pos + 2 <= message.length) {
          const len = u16leAt(message, pos)
          pos += 2
          if (pos + len <= message.length) {
            record('string', message.subarray(pos, pos + len).toString('utf8'))
            pos += len
          }
        }
      } else if (typeByte === 0x21) {
        if (pos < message.length) {
          const len = message[pos]
          pos += 1
          if (pos + len <= message.length) {
            record('string', message.subarray(pos, pos + len).toString('utf8'))
            pos += len
          }
        }
      } else if (typeByte === 0x30) {
        if (pos + 2 <= message.length) {
          const len = u16leAt(message, pos)
          pos += 2
          if (pos + len <= message.length) {
            record('raw', Buffer.from(message.subarray(pos, pos + len)))
            pos += len
          }
        }
      } else if (typeByte === 0x31) {
        if (pos < message.length) {
          const len = message[pos]
          pos += 1
          if (pos + len <= message.length) {
            record('raw', Buffer.from(message.subarray(pos, pos + len)))
            pos += len
          }
        }
      } else if (typeByte === 0x28) {
        if (pos + 2 <= message.length) {
          const len = u16leAt(message, pos)
          pos += 2
          if (pos + len <= message.length) {
            record('msg', Buffer.from(message.subarray(pos, pos + len)))
            pos += len
          }
        }
      } else if (typeByte === 0x29) {
        if (pos < message.length) {
          const len = message[pos]
          pos += 1
          if (pos + len <= message.length) {
            record('msg', Buffer.from(message.subarray(pos, pos + len)))
            pos += len
          }
        }
      } else if (typeByte === 0xa0) {
        if (pos + 2 <= message.length) {
          const count = u16leAt(message, pos)
          pos += 2
          for (let i = 0; i < count; i += 1) {
            if (pos + 2 > message.length) break
            const len = u16leAt(message, pos)
            pos += 2
            pos += len
          }
          record('str_array', null)
        }
      } else if (typeByte === 0xa8) {
        if (pos + 2 <= message.length) {
          const count = u16leAt(message, pos)
          pos += 2
          for (let i = 0; i < count; i += 1) {
            if (pos + 2 > message.length) break
            const len = u16leAt(message, pos)
            pos += 2
            pos += len
          }
          record('msg_array', null)
        }
      } else {
        // Unknown type: cannot continue parsing reliably (same as Python).
        break
      }
    }
    return result
  }

  static getSysTo (parsed) {
    const field = fieldOf(parsed, 0xff0001)
    return field && field.type === 'u32_array' ? field.value : null
  }

  static getSysFrom (parsed) {
    const field = fieldOf(parsed, 0xff0002)
    return field && field.type === 'u32_array' ? field.value : null
  }

  static getSysCmd (parsed) {
    const field = fieldOf(parsed, 0xff0007)
    return field ? field.value : null
  }

  static getSysReqId (parsed) {
    const field = fieldOf(parsed, 0xff0006)
    return field ? field.value : null
  }

  static getSessionId (parsed) {
    const field = fieldOf(parsed, 0xfe0001)
    return field ? field.value : null
  }

  static getKey2Raw (parsed) {
    const field = fieldOf(parsed, 0x000002)
    return field && field.type === 'raw' ? field.value : null
  }

  static getSysStatus (parsed) {
    const field = fieldOf(parsed, 0xff0008)
    return field ? field.value : null
  }
}

// ---------------------------------------------------------------------------
// Wire framing: [chunk_len][tag][payload] chunks
// ---------------------------------------------------------------------------

/**
 * Chunk a complete (already encrypted) payload for transmission.
 * Mirrors the Python chunker exactly, including the extra zero-length final
 * chunk when the payload length is an exact multiple of 255.
 */
export function encodeFrameChunks (fullMessage, firstTag = 0x06) {
  const chunks = []
  let remaining = toBytes(fullMessage)
  let tag = firstTag
  for (;;) {
    const frameLen = remaining.length >= CHUNK_MAX ? CHUNK_MAX : remaining.length
    chunks.push(Buffer.from([frameLen, tag]), remaining.subarray(0, frameLen))
    if (remaining.length >= CHUNK_MAX) {
      remaining = remaining.subarray(CHUNK_MAX)
      tag = 0xff
    } else {
      break
    }
  }
  return Buffer.concat(chunks)
}

/**
 * Incremental decoder for the chunk framing. push() accepts arbitrarily split
 * TCP data and returns every complete reassembled payload.
 *
 * Note: unlike the Python reference (which can return a partial payload when
 * the buffer ends exactly on a full 0xFF chunk), this decoder waits for the
 * terminal chunk (`chunk_len < 0xFF`, possibly 0) before emitting a frame.
 */
export class FrameDecoder {
  constructor () {
    this._buffer = Buffer.alloc(0)
  }

  get bufferedBytes () {
    return this._buffer.length
  }

  reset () {
    this._buffer = Buffer.alloc(0)
  }

  push (chunk) {
    this._buffer = Buffer.concat([this._buffer, toBytes(chunk)])
    const frames = []
    for (;;) {
      const frame = this._extractOne()
      if (frame === null) break
      frames.push(frame)
    }
    return frames
  }

  _extractOne () {
    const buffer = this._buffer
    const parts = []
    let pos = 0
    for (;;) {
      if (pos + 2 > buffer.length) return null
      const chunkLen = buffer[pos]
      pos += 2 // skip chunk length + tag byte
      if (pos + chunkLen > buffer.length) return null
      parts.push(buffer.subarray(pos, pos + chunkLen))
      pos += chunkLen
      if (chunkLen < CHUNK_MAX) {
        this._buffer = buffer.subarray(pos)
        return Buffer.concat(parts)
      }
    }
  }
}
